use xiom.io;

use xiom.string;
fn parse_score(raw: Str) -> Result[Int, Str] {
  return string.str_to_int(raw);
}

fn validate_score(score: Int) -> Result[Int, Str] {
  if score < 0 { return Err("Score cannot be negative"); }
  if score > 100 { return Err("Score cannot exceed 100"); }
  return Ok(score);
}

fn grade_score(score: Int) -> Result[Str, Str] {
  if score >= 90 { return Ok("A"); }
  if score >= 80 { return Ok("B"); }
  if score >= 70 { return Ok("C"); }
  if score >= 60 { return Ok("D"); }
  return Ok("F");
}

fn process_score(raw: Str) -> Result[Str, Str] {
  let parsed = parse_score(raw)?;
  let valid = validate_score(parsed)?;
  let grade = grade_score(valid)?;
  return Ok(grade);
}

fn main() -> Int {
  match process_score("95") { Ok(g) => io.println(g.to_str()) Err(e) => io.println(e.to_str()) };
  match process_score("72") { Ok(g) => io.println(g.to_str()) Err(e) => io.println(e.to_str()) };
  match process_score("-5") { Ok(g) => io.println(g.to_str()) Err(e) => io.println(e.to_str()) };
  match process_score("200") { Ok(g) => io.println(g.to_str()) Err(e) => io.println(e.to_str()) };
  match process_score("abc") { Ok(g) => io.println(g.to_str()) Err(e) => io.println(e.to_str()) };
  return 0;
}
